package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem string
	DrPrice decimal.Decimal
	DrPct int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec

var discLines []string
var discIdx int
var discEOF bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func setInputDone() {
	WsEofFlag = "Y"
}

func pow10(n int64) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func store95V99(d decimal.Decimal) decimal.Decimal {
	// keep low-order 7 digits of scaled value (5 int + 2 frac)
	scaled := d.Shift(2).Truncate(0)
	modBase := pow10(7)
	m := scaled.Mod(modBase)
	// shopspring Mod keeps sign of dividend; fine
	return m.Shift(-2)
}

func store98V99(d decimal.Decimal) decimal.Decimal {
	scaled := d.Shift(2).Truncate(0)
	modBase := pow10(10)
	m := scaled.Mod(modBase)
	return m.Shift(-2)
}

func store93(v int64) int64 {
	m := v % 1000
	if m < 0 {
		m += 1000
	}
	return m
}

func parsePriceField(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// keep digits only; if contains non-digits treat as 0? assume digits
	// remove leading +/-? assume positive
	neg := false
	if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	} else if strings.HasPrefix(t, "+") {
		t = t[1:]
	}
	// collect digits
	var b strings.Builder
	for _, c := range t {
		if c >= '0' && c <= '9' {
			b.WriteRune(c)
		} else if c == ' ' {
			continue
		} else {
			// non-digit: treat as zero? ignore
		}
	}
	ds := b.String()
	if ds == "" {
		return decimal.NewFromInt(0)
	}
	// parse as integer (may be up to 7 digits, fits int64)
	var n int64
	for _, c := range ds {
		n = n*10 + int64(c-'0')
	}
	d := decimal.New(n, -2)
	if neg {
		d = d.Neg()
	}
	return d
}

func parsePctField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	neg := false
	if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	} else if strings.HasPrefix(t, "+") {
		t = t[1:]
	}
	var n int64
	found := false
	for _, c := range t {
		if c >= '0' && c <= '9' {
			found = true
			n = n*10 + int64(c-'0')
		}
	}
	if !found {
		return 0
	}
	if neg {
		n = -n
	}
	// keep low-order 2 digits? COBOL field read: value is as stored; fit in 2 digits
	// just return n mod 100 preserving? Assume 0-99
	return n
}

func formatEdited(val decimal.Decimal, pattern string, intDigits int) string {
	// pattern includes ',' '.' ; intDigits = count of Z/9 in integer part
	// value assumed scaled 2; truncate toward zero to 2 decimals for display
	v := val.Truncate(2)
	neg := v.IsNegative()
	av := v.Abs()
	intPart := av.Truncate(0)
	fracPart := av.Sub(intPart).Shift(2).Truncate(0)
	// frac 0..99
	fracInt := fracPart.IntPart()
	if fracInt < 0 {
		fracInt = 0
	}
	if fracInt > 99 {
		fracInt = 99
	}
	// integer digits with overflow truncation
	modBase := pow10(int64(intDigits))
	m := intPart.Mod(modBase)
	intInt := m.IntPart()
	// build zero-padded digit string length intDigits
	digits := make([]byte, intDigits)
	tmp := intInt
	for i := intDigits - 1; i >= 0; i-- {
		digits[i] = byte('0' + tmp%10)
		tmp /= 10
	}
	// map to pattern
	// find dot position
	dotIdx := strings.Index(pattern, ".")
	intPat := pattern
	fracPat := ""
	if dotIdx >= 0 {
		intPat = pattern[:dotIdx]
		fracPat = pattern[dotIdx+1:]
	}
	_ = fracPat
	out := make([]byte, 0, len(pattern)+2)
	significant := false
	// need to know for each intPat char, which digit index it corresponds to
	// count digit slots in intPat
	// iterate left to right
	digitIdx := 0
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			d := digits[digitIdx]
			digitIdx++
			if c == 'Z' {
				if d != '0' {
					significant = true
					out = append(out, d)
				} else {
					if significant {
						out = append(out, '0')
					} else {
						// check if any later non-zero? No: leading zero -> space
						// But need to look ahead? Standard Z suppression: if all more significant are zero, space.
						// Since we track significant from left, this works.
						out = append(out, ' ')
					}
				}
			} else { // '9'
				out = append(out, d)
				// '9' forces significance for commas to left? Already to left done.
				// For trailing? no more commas after last digit.
			}
		} else if c == ',' {
			if significant {
				out = append(out, ',')
			} else {
				out = append(out, ' ')
			}
		} else {
			out = append(out, c)
		}
	}
	// decimal point
	if dotIdx >= 0 {
		out = append(out, '.')
		// frac digits: exactly len(fracPat) digits, zero padded
		fracStr := fmt.Sprintf("%02d", fracInt)
		// if fracPat length != 2, adjust (always 2 here)
		for len(fracStr) < len(fracPat) {
			fracStr += "0"
		}
		if len(fracStr) > len(fracPat) {
			fracStr = fracStr[:len(fracPat)]
		}
		out = append(out, []byte(fracStr)...)
	}
	_ = neg
	return string(out)
}

func moveToPriceEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZ9.99", 5)
}
func moveToTotalEd(d decimal.Decimal) string {
	return formatEdited(d, "ZZ,ZZZ,ZZ9.99", 8)
}

func fmtCount(v int64) string {
	// PIC 9(3) zero-padded
	// ensure 0..999
	x := v % 1000
	if x < 0 {
		x += 1000
	}
	return fmt.Sprintf("%03d", x)
}

func fmtPct(v int64) string {
	x := v % 100
	if x < 0 {
		x += 100
	}
	return fmt.Sprintf("%02d", x)
}

func MAINPARA() {
	// OPEN INPUT DISC-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// empty file behaviour: treat as no records
		discLines = nil
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		const maxCap = 1024 * 1024
		buf := make([]byte, 0, 4096)
		sc.Buffer(buf, maxCap)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if present (Scanner already strips \n, keeps \r? remove)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			discLines = append(discLines, line)
		}
		f.Close()
	}
	discIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DISC-FILE (already closed)
	SUMMARYPARA()
}

func READPARA() {
	if discIdx >= len(discLines) {
		setInputDone()
		return
	}
	line := discLines[discIdx]
	discIdx++
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	item := line[0:6]
	priceField := line[6:13]
	pctField := line[13:15]
	discRec.DrItem = item
	discRec.DrPrice = parsePriceField(priceField)
	discRec.DrPct = parsePctField(pctField)
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct))
	quot := prod.Shift(-2)
	rounded := quot.Round(2)
	WsDiscount = store95V99(rounded)
	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netRaw := discRec.DrPrice.Sub(WsDiscount).Truncate(2)
	WsNet = store95V99(netRaw)
	// ADD WS-NET TO WS-TOTAL-NET
	totRaw := WsTotalNet.Add(WsNet)
	// truncate to scale (already) then store with overflow
	WsTotalNet = store98V99(totRaw.Truncate(2))
	// ADD 1 TO WS-COUNT
	WsCount = store93(WsCount + 1)
	WsPriceEd = moveToPriceEd(discRec.DrPrice)
	WsDiscEd = moveToPriceEd(WsDiscount)
	WsNetEd = moveToPriceEd(WsNet)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, fmtPct(discRec.DrPct), WsDiscEd, WsNetEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = moveToTotalEd(WsTotalNet)
	fmt.Printf("%s%s%s%s\n", "ITEMS: "+fmtCount(WsCount), " NET TOTAL: ", WsTotalEd, "")
}

func main() {
	MAINPARA()
}
